def polynomial_to_string(n: int, coeffs: List[int]) -> str:
    """
    Converts a list of polynomial coefficients into a formatted string representation.

    Args:
        n (int): The highest degree of the polynomial.
        coeffs (List[int]): A list of coefficients, starting with the coefficient of the highest degree term.

    Returns:
        str: The string representation of the polynomial.
    """
    terms = []
    first_term = True
    for degree, coeff in zip(range(n, -1, -1), coeffs):
        if coeff == 0:
            continue

        # Determine sign
        if first_term:
            sign = '-' if coeff < 0 else ''
        else:
            sign = '-' if coeff < 0 else '+'

        abs_coeff = abs(coeff)

        # Determine variable part
        if degree == 0:
            var_part = ''
        elif degree == 1:
            var_part = 'x'
        else:
            var_part = f'x^{degree}'

        # Determine coefficient part
        if abs_coeff == 1 and degree > 0:
            coeff_part = ''
        else:
            coeff_part = str(abs_coeff)

        term = f"{sign}{coeff_part}{var_part}"
        terms.append(term)
        first_term = False

    if not terms:
        return '0'
    return ''.join(terms)

def decode(encoded: str, original: str, message: str) -> str:
    """
    Decodes an encrypted message using a cipher derived from a known encoded-original pair.

    The function builds a mapping from encoded letters to their original letters and uses this
    mapping to decode a given encrypted message. If a contradiction is found during mapping
    construction, or not all letters are represented in the mapping, the function returns "Failed".

    Args:
    encoded (str): A string representing the encoded information.
    original (str): A string representing the original information corresponding to the encoded string.
    message (str): A string representing the encrypted message to be decoded.

    Returns:
    str: The decoded message if successful, or "Failed" if the decoding is not possible.
    """
    # The mapping must be built from the encoded-original pair
    if len(encoded) != len(original):
        return "Failed"

    mapping = {}
    for e, o in zip(encoded, original):
        if e in mapping:
            if mapping[e] != o:
                return "Failed"
        else:
            mapping[e] = o

    # The mapping must be a bijection covering all 26 uppercase letters
    if len(mapping) != 26:
        return "Failed"
    if len(set(mapping.values())) != 26:
        return "Failed"

    # Decode the message using the mapping
    decoded_chars = []
    for ch in message:
        if ch not in mapping:
            return "Failed"
        decoded_chars.append(mapping[ch])

    return "".join(decoded_chars)

def generate_numbers(n, rules) -> int:
    """
    Generate all unique numbers from the given number by applying transformation rules.

    Each rule allows a single digit to be transformed into another. A breadth-first search
    (BFS) is used to explore all possible transformations. The function returns the count
    of unique numbers that can be generated from the original number, including the number itself.

    Args:
    - n (int): The original integer number to transform.
    - rules (list of tuples): A list of transformation rules, where each rule is represented
                              as a tuple (x, y) indicating that digit x can be transformed into y.

    Returns:
    - int: The total count of unique numbers that can be generated.
    """
    # Input validation
    if not isinstance(n, int):
        raise TypeError("n must be an integer")
    if not isinstance(rules, list):
        raise TypeError("rules must be a list")
    mapping = {}
    for rule in rules:
        if not (isinstance(rule, tuple) and len(rule) == 2):
            raise ValueError("Each rule must be a tuple of two integers")
        x, y = rule
        if not (isinstance(x, int) and isinstance(y, int)):
            raise ValueError("Rule elements must be integers")
        if not (0 <= x <= 9 and 0 <= y <= 9):
            raise ValueError("Digits must be between 0 and 9")
        mapping.setdefault(x, []).append(y)

    start = str(n)
    visited = {start}
    queue = [start]

    while queue:
        current = queue.pop(0)
        for i, ch in enumerate(current):
            d = int(ch)
            if d in mapping:
                for y in mapping[d]:
                    new_num = current[:i] + str(y) + current[i+1:]
                    if new_num not in visited:
                        visited.add(new_num)
                        queue.append(new_num)

    return len(visited)

def check_scenario(scenario: str, liar_count: set, statements: dict, days_of_week: set) -> bool:
    """
    Evaluates the consistency of a scenario where one participant is the criminal based on the given statements.

    Parameters:
    - scenario (str): The name of the participant being tested as the potential criminal.
    - liar_count (set): A set of names of participants who are assumed to be liars.
    - statements (dict): A dictionary mapping participant names to lists of their respective statements.
    - days_of_week (set): A set of strings representing the days of the week.

    Returns:
    - bool: True if the scenario is consistent with the statements, False otherwise.
    """
    # Helper to determine truth of a statement about guilt
    def evaluate(statement: str, speaker: str) -> bool:
        # Normalize statement for simple parsing
        stmt = statement.strip().upper()
        # Check for day of week mention; ignore such statements
        if any(day.upper() in stmt for day in days_of_week):
            return None  # indicates to ignore

        # Patterns to handle
        if stmt == "I AM GUILTY.":
            return speaker == scenario
        if stmt == "I AM NOT GUILTY.":
            return speaker != scenario
        # Expect format "NAME IS GUILTY." or "NAME IS NOT GUILTY."
        parts = stmt.split()
        if len(parts) >= 4 and parts[1] == "IS":
            target = parts[0]
            if parts[2] == "GUILTY.":
                return target == scenario
            if parts[2] == "NOT" and parts[3] == "GUILTY.":
                return target != scenario
        # If statement doesn't match known patterns, treat as neutral (no constraint)
        return None

    for speaker, stmts in statements.items():
        for stmt in stmts:
            truth = evaluate(stmt, speaker)
            if truth is None:
                continue  # ignore or neutral statement
            if speaker in liar_count:
                if truth:
                    return False  # liar said a true statement
            else:
                if not truth:
                    return False  # truth-teller said a false statement
    return True
